create extension if not exists "pgcrypto";
create extension if not exists "vector";
create extension if not exists "pg_trgm";

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,name text,avatar_url text,country text,bio text,created_at timestamptz not null default now());
create table public.brands(id uuid primary key default gen_random_uuid(),name text unique not null,country text,tier text,logo_url text);
create table public.notes(id uuid primary key default gen_random_uuid(),name text unique not null);
create table public.accords(id uuid primary key default gen_random_uuid(),name text unique not null);
create table public.fragrances(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,brand_id uuid not null references public.brands(id),release_year int,concentration text,description text,hero_image_url text,longevity_hrs numeric,projection text,seasons text[] not null default '{}',occasions text[] not null default '{}',price_tier_usd int,discontinued boolean not null default false,embedding vector(1536),created_at timestamptz not null default now());
create index fragrances_brand_idx on public.fragrances(brand_id);
create index fragrances_name_trgm_idx on public.fragrances using gin(name gin_trgm_ops);
create index fragrances_embedding_idx on public.fragrances using hnsw(embedding vector_cosine_ops);
create table public.fragrance_notes(fragrance_id uuid not null references public.fragrances(id) on delete cascade,note_id uuid not null references public.notes(id) on delete cascade,position text not null,primary key(fragrance_id,note_id));
create table public.fragrance_accords(fragrance_id uuid not null references public.fragrances(id) on delete cascade,accord_id uuid not null references public.accords(id) on delete cascade,strength numeric not null default 1,primary key(fragrance_id,accord_id));
create table public.dna_scores(id uuid primary key default gen_random_uuid(),fragrance_id uuid not null unique references public.fragrances(id) on delete cascade,sweetness numeric not null,freshness numeric not null,masculine_feminine numeric not null,projection numeric not null,longevity numeric not null,versatility numeric not null,sample_size int not null default 0);
create table public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,fragrance_id uuid not null references public.fragrances(id) on delete cascade,rating int not null check(rating between 1 and 5),body text,longevity_hrs numeric,projection text,created_at timestamptz not null default now());
create table public.collection_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,fragrance_id uuid not null references public.fragrances(id) on delete cascade,type text not null check(type in('bottle','decant','wishlist','empty')),bottle_size_ml int,ml_remaining numeric,purchase_price numeric,purchased_at timestamptz,created_at timestamptz not null default now());
create table public.decant_listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.profiles(id) on delete cascade,fragrance_id uuid not null references public.fragrances(id) on delete cascade,ml_amount numeric not null,price numeric not null,currency text not null default 'USD',condition text not null,status text not null default 'active',photos text[] not null default '{}',created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.decant_listings(id),buyer_id uuid not null references public.profiles(id),seller_id uuid not null references public.profiles(id),amount numeric not null,status text not null default 'pending',tracking_number text,escrow_release_at timestamptz,created_at timestamptz not null default now());
create table public.price_points(id uuid primary key default gen_random_uuid(),fragrance_id uuid not null references public.fragrances(id) on delete cascade,retailer text not null,price numeric not null,currency text not null default 'USD',url text not null,in_stock boolean not null default true,captured_at timestamptz not null default now());
create table public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null,fragrance_id uuid references public.fragrances(id),image_url text,caption text,created_at timestamptz not null default now());
create table public.likes(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,post_id uuid not null references public.posts(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,post_id));
create table public.comments(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,post_id uuid not null references public.posts(id) on delete cascade,body text not null,created_at timestamptz not null default now());
create table public.advisor_submissions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,inputs jsonb not null,result_json jsonb not null,created_at timestamptz not null default now());
create table public.chat_sessions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,title text,created_at timestamptz not null default now());
create table public.chat_messages(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.chat_sessions(id) on delete cascade,role text not null,content text not null,created_at timestamptz not null default now());
create table public.layering_suggestions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,fragrance_ids uuid[] not null,combination jsonb not null,created_at timestamptz not null default now());
